@pytest.mark.parametrize("project_Eckart", [None, "both", "translational", "rotational"])
def test_c3h_complex_salc_values(project_Eckart):
    mol = molsym.Molecule.from_file(TEST_DIR / "sxyz" / "C3h.xyz")
    mol = molsym.symmetrize(mol)
    symtext = molsym.Symtext.from_molecule(mol)
    assert symtext.complex

    cart_coords = molsym.salcs.CartesianCoordinates(symtext)
    salcs = molsym.salcs.projection_op.ProjectionOp(symtext, cart_coords, project_Eckart=project_Eckart)

    ref = c3h_eckart_ref[project_Eckart]
    assert [s.irrep.symbol for s in salcs.salcs] == ref["irreps"]
    for j, s in enumerate(salcs.salcs):
        assert s.coeffs.dtype == np.float64
        np.testing.assert_allclose(s.coeffs, ref["coeffs"][j], atol=1e-8)

    B = np.array([s.coeffs for s in salcs.salcs])
    np.testing.assert_allclose(B @ B.T, np.eye(B.shape[0]), atol=1e-8)

